(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.04+t*0.5)*5 + Math.cos(my*0.035-t*0.45)*4;
  const w2y = Math.cos(my*0.04-t*0.4)*5 + Math.sin(mx*0.038+t*0.55)*4;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+1)*60, 40+Math.cos(t*0.65+3)*40, 0.11, 2.1],
    [400+Math.cos(t*0.55+2)*70, 220+Math.sin(t*0.75+4)*50, 0.05, 1.8]
  ];
  let aS=0, iS=0, hS=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    hS += Math.sin(d*f*1.3 - t*sp*0.4 + 2.8);
  }
  const act=aS/8, inh=iS/8, hrm=hS/8;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(sx*0.08+t*1.5)*Math.sin(sy*0.07-t*1.2)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2);
  const sp2 = Math.sin(dist*0.08-ang*2-t*2.1)*0.3+Math.sin(dist*0.03+ang*6-t*0.8)*0.2;
  const r1 = act - inh*0.7 + (bg1+bg2+bg3)*0.25 + sp1*0.4+sp2;
  const r2 = act*0.5 - hrm*0.8 + inh*0.3 + sp1*0.3;
  const cross = r1*r2*0.3;
  const reaction = Math.tanh((r1+cross)*2.2);
  const reaction2 = Math.tanh((r2-cross)*1.8);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.28-t*2.7)*0.08*reaction;
  const edge = Math.abs(reaction)>0.6 ? 1.0+Math.abs(reaction)*0.3 : 1.0;
  const blend = reaction*0.5+reaction2*0.2+cell*0.15+cross*0.1+micro*0.05;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,55],[10,35,85],[12,65,110],[18,100,125],
    [30,135,130],[80,160,120],[160,175,85],
    [210,185,65],[220,145,60],[195,95,65],
    [160,55,65],[100,30,65],[50,18,55],[5,12,55]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.25;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge)|0
  ];
}
